//! Equivalence with Cassino's learner (`docs/TUTOR.md` section 13): with
//! Cassino's ladder and constants written out as a `Ladder` and `Params`
//! (`tests/common/mod.rs`), the crate gives the same mastery, state, focus
//! and `just_mastered` as `cassino_core::learner::learn`, and the same text
//! form of a summary, on every case of `tests/fixtures/cassino_learner.txt`.
//!
//! The fixture was generated by running Cassino's own code (cassino-core @
//! 73f0cd7, `learner.rs` unchanged since) with
//! `tests/fixtures/cassino_learner_gen.rs`: the scenarios of Cassino's
//! learner tests, the exact thresholds (`edge-*`), then 100 sequences of 1 to 10 deals from a fixed LCG. The
//! generator's header says how to run it (a scratch crate with a path
//! dependency on `cassino-core`; Cassino is not touched). Regenerate it
//! whenever STAMP's Cassino commit moves, and keep this test passing.
//!
//! One difference is deliberate: an exact tie in gain goes to the earlier
//! skill here and to the later in Cassino (`docs/TUTOR.md` section 1). The
//! generator drops every case with such a tie, and `learn.rs` tests the rule.
//!
//! Fixture format, per case: `case <name>`; per deal `deal` and the
//! summary's text form; `expect games=<n> focus=<slug|-> just=<slugs|->`;
//! a line `state <slug> <mastered 0|1> <chances> <met> <cost> <gain>` per
//! skill; `end`. Floats are Rust `{:?}`, so they read back exactly.

mod common;

use common::*;
use kit_learner::{learn, Summary};

const FIXTURE: &str = include_str!("fixtures/cassino_learner.txt");

struct Case {
    name: String,
    deals: Vec<String>,
    expect: String,
    states: Vec<String>,
}

fn cases() -> Vec<Case> {
    let mut out = Vec::new();
    let mut lines = FIXTURE.lines();
    while let Some(line) = lines.next() {
        let name = line.strip_prefix("case ").expect("a case").to_string();
        let (mut deals, mut states, mut expect) = (Vec::new(), Vec::new(), String::new());
        for line in lines.by_ref() {
            if line == "deal" {
                deals.push(String::new());
            } else if let Some(e) = line.strip_prefix("expect ") {
                expect = e.to_string();
            } else if line.starts_with("state ") {
                states.push(line.to_string());
            } else if line == "end" {
                break;
            } else {
                let d = deals.last_mut().expect("a deal");
                d.push_str(line);
                d.push('\n');
            }
        }
        out.push(Case {
            name,
            deals,
            expect,
            states,
        });
    }
    out
}

fn slugs(v: &[usize]) -> String {
    if v.is_empty() {
        "-".into()
    } else {
        v.iter()
            .map(|&i| SKILLS[i].slug)
            .collect::<Vec<_>>()
            .join(",")
    }
}

#[test]
fn the_crate_gives_cassinos_mastery_and_focus_on_cassinos_summaries() {
    let cases = cases();
    assert!(cases.len() > 100, "{} cases", cases.len());
    let mut with_focus = 0;
    let mut with_mastery = 0;
    for case in &cases {
        let games: Vec<Summary> = case
            .deals
            .iter()
            .map(|t| Summary::parse(&LADDER, t).unwrap_or_else(|e| panic!("{}: {e}", case.name)))
            .collect();
        // The text form is Cassino's, byte for byte.
        for (g, t) in games.iter().zip(&case.deals) {
            assert_eq!(g.to_text(&LADDER), t.trim_end(), "{}", case.name);
        }
        let l = learn(&LADDER, &PARAMS, &games);
        let expect = format!(
            "games={} focus={} just={}",
            l.games,
            l.focus.map_or("-", |f| SKILLS[f].slug),
            slugs(&l.just_mastered)
        );
        assert_eq!(expect, case.expect, "{}", case.name);
        assert_eq!(case.states.len(), SKILLS.len(), "{}", case.name);
        for (i, line) in case.states.iter().enumerate() {
            let s = l.state(i);
            let got = format!(
                "state {} {} {:?} {:?} {:?} {:?}",
                SKILLS[i].slug,
                u8::from(s.mastered),
                s.chances,
                s.met,
                s.cost,
                s.gain
            );
            assert_eq!(&got, line, "{}", case.name);
        }
        with_focus += usize::from(l.focus.is_some());
        with_mastery += usize::from(l.skills.iter().any(|s| s.mastered));
    }
    // The fixture exercises both outcomes, not only the easy one.
    assert!(with_focus > 50 && with_focus < cases.len(), "{with_focus}");
    assert!(with_mastery > 20, "{with_mastery}");
}
